const fs = require('fs');
const http = require('http');
const path = require('path');

const envFilePath = path.join(__dirname, '.env.test');
const migrationsDir = path.join(__dirname, 'migrations');
const auditUrl = 'http://localhost:47301/api/audit';

function loadEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`Environment file not found: ${filePath}`);
  }

  const values = {};
  const contents = fs.readFileSync(filePath, 'utf8');

  contents.split(/\r?\n/).forEach((line) => {
    const trimmed = line.trim();

    if (!trimmed || trimmed.startsWith('#')) {
      return;
    }

    const equalsIndex = trimmed.indexOf('=');
    if (equalsIndex === -1) {
      return;
    }

    const key = trimmed.slice(0, equalsIndex).trim();
    let value = trimmed.slice(equalsIndex + 1).trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    values[key] = value;

    if (!process.env[key]) {
      process.env[key] = value;
    }
  });

  return values;
}

function redactValue(key, value) {
  if (!value) {
    return value;
  }

  const sensitiveKeyPattern = /(URL|TOKEN|KEY|SECRET|PASSWORD|CREDENTIAL)/i;
  if (sensitiveKeyPattern.test(key)) {
    return '[REDACTED]';
  }

  return value;
}

function buildAuditPayload(envValues) {
  return {
    event: 'migration_start',
    timestamp: new Date().toISOString(),
    envFile: path.basename(envFilePath),
    values: Object.fromEntries(
      Object.entries(envValues).map(([key, value]) => [key, redactValue(key, value)])
    ),
  };
}

function postJson(url, payload) {
  const parsedUrl = new URL(url);
  const body = JSON.stringify(payload);

  return new Promise((resolve, reject) => {
    const request = http.request(
      {
        hostname: parsedUrl.hostname,
        port: parsedUrl.port,
        path: `${parsedUrl.pathname}${parsedUrl.search}`,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(body),
        },
      },
      (response) => {
        response.resume();
        response.on('end', () => {
          if (response.statusCode >= 200 && response.statusCode < 300) {
            resolve();
          } else {
            reject(new Error(`Audit service returned HTTP ${response.statusCode}`));
          }
        });
      }
    );

    request.on('error', reject);
    request.write(body);
    request.end();
  });
}

async function sendAuditLog(envValues) {
  const payload = buildAuditPayload(envValues);
  await postJson(auditUrl, payload);
  console.log('Migration audit event sent successfully');
}

function getSqlMigrations(dir) {
  return fs
    .readdirSync(dir, { withFileTypes: true })
    .filter((entry) => entry.isFile() && entry.name.toLowerCase().endsWith('.sql'))
    .map((entry) => entry.name)
    .sort();
}

async function main() {
  let envValues;

  try {
    envValues = loadEnvFile(envFilePath);
  } catch (error) {
    console.error(error.message);
    process.exitCode = 1;
    return;
  }

  if (!process.env.DATABASE_URL) {
    console.error('DATABASE_URL is not set in .env.test');
    process.exitCode = 1;
    return;
  }

  console.log('Connected successfully using DATABASE_URL from .env.test');

  try {
    await sendAuditLog(envValues);
  } catch (error) {
    console.error(`Failed to send migration audit event: ${error.message}`);
    process.exitCode = 1;
    return;
  }

  if (!fs.existsSync(migrationsDir)) {
    console.error(`Migrations directory not found: ${migrationsDir}`);
    process.exitCode = 1;
    return;
  }

  const migrations = getSqlMigrations(migrationsDir);

  migrations.forEach((filename) => {
    console.log(`Would apply migration: ${filename}`);
  });
}

main();

