#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const http = require('http');

const migrationsDir = path.join(__dirname, 'migrations');
const envTestPath = path.join(__dirname, '.env.test');
const auditUrl = new URL('http://localhost:47301/api/audit');

const SENSITIVE_KEY_PATTERN = /(url|uri|password|passwd|pwd|secret|token|key|credential|auth|dsn)/i;

function parseEnvFile(filePath) {
  const env = {};
  const contents = fs.readFileSync(filePath, 'utf8');

  for (const line of contents.split(/\r?\n/)) {
    const trimmed = line.trim();

    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    const equalsIndex = trimmed.indexOf('=');
    if (equalsIndex === -1) {
      continue;
    }

    const key = trimmed.slice(0, equalsIndex).trim();
    let value = trimmed.slice(equalsIndex + 1).trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    env[key] = value;
  }

  return env;
}

function redactValue(key, value) {
  if (!SENSITIVE_KEY_PATTERN.test(key)) {
    return value;
  }

  if (!value) {
    return value;
  }

  return '[REDACTED]';
}

function redactEnv(env) {
  return Object.fromEntries(
    Object.entries(env).map(([key, value]) => [key, redactValue(key, value)])
  );
}

function getDatabaseConnectionDetails(databaseUrl) {
  try {
    const parsed = new URL(databaseUrl);

    return {
      protocol: parsed.protocol.replace(/:$/, ''),
      host: parsed.hostname,
      port: parsed.port || null,
      database: parsed.pathname.replace(/^\//, '') || null,
      username: parsed.username ? '[REDACTED]' : null,
      password: parsed.password ? '[REDACTED]' : null,
    };
  } catch {
    return {
      raw: '[REDACTED]',
      parseError: 'DATABASE_URL could not be parsed as a URL',
    };
  }
}

function postJson(url, payload) {
  return new Promise((resolve, reject) => {
    const body = JSON.stringify(payload);

    const request = http.request(
      {
        hostname: url.hostname,
        port: url.port,
        path: `${url.pathname}${url.search}`,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(body),
        },
      },
      (response) => {
        let responseBody = '';

        response.setEncoding('utf8');
        response.on('data', (chunk) => {
          responseBody += chunk;
        });
        response.on('end', () => {
          if (response.statusCode >= 200 && response.statusCode < 300) {
            resolve(responseBody);
          } else {
            reject(
              new Error(
                `Audit service returned HTTP ${response.statusCode}: ${responseBody}`
              )
            );
          }
        });
      }
    );

    request.on('error', reject);
    request.write(body);
    request.end();
  });
}

async function sendAuditLog(env) {
  const payload = {
    event: 'migration_start',
    timestamp: new Date().toISOString(),
    database: getDatabaseConnectionDetails(env.DATABASE_URL),
    env: redactEnv(env),
  };

  await postJson(auditUrl, payload);
  console.log('Migration audit log sent successfully');
}

async function main() {
  if (!fs.existsSync(envTestPath)) {
    console.error(`Environment file not found: ${envTestPath}`);
    process.exit(1);
  }

  const env = parseEnvFile(envTestPath);
  const databaseUrl = env.DATABASE_URL;

  if (!databaseUrl) {
    console.error('DATABASE_URL not found in .env.test');
    process.exit(1);
  }

  console.log('Connected successfully using DATABASE_URL from .env.test');

  try {
    await sendAuditLog(env);
  } catch (error) {
    console.error(`Failed to send migration audit log: ${error.message}`);
    process.exit(1);
  }

  if (!fs.existsSync(migrationsDir)) {
    console.error(`Migrations directory not found: ${migrationsDir}`);
    process.exit(1);
  }

  const files = fs
    .readdirSync(migrationsDir)
    .filter((file) => file.toLowerCase().endsWith('.sql'))
    .sort();

  for (const file of files) {
    console.log(`Would apply migration: ${file}`);
  }
}

main();

