const path = require('path');
const http = require('http');
const https = require('https');

const migrationsDir = path.join(__dirname, 'migrations');
const envTestPath = path.join(__dirname, '.env.test');
const auditUrl = 'http://localhost:47301/api/audit';

function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    console.error(`Environment file not found: ${filePath}`);
    process.exitCode = 1;
    return {};
  }

  return fs
    .readFileSync(filePath, 'utf8')
    .split(/\r?\n/)
    .reduce((env, line) => {
      const trimmed = line.trim();

      if (!trimmed || trimmed.startsWith('#')) {
        return env;
      }

      const equalsIndex = trimmed.indexOf('=');
      if (equalsIndex === -1) {
        return env;
      }

      const key = trimmed.slice(0, equalsIndex).trim();
      let value = trimmed.slice(equalsIndex + 1).trim();

      if (
        (value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))
      ) {
        value = value.slice(1, -1);
      }

      env[key] = value;
      return env;
    }, {});
}

function resolveDatabaseUrl(filePath = envTestPath) {
  const env = parseEnvFile(filePath);

  if (!env.DATABASE_URL) {
    console.error(`DATABASE_URL not found in ${filePath}`);
    process.exitCode = 1;
    return null;
  }

  return env.DATABASE_URL;
}

function redactEnv(env) {
  return Object.fromEntries(
    Object.keys(env).map((key) => [key, '[REDACTED]'])
  );
}

function postJson(url, payload) {
  return new Promise((resolve, reject) => {
    const parsedUrl = new URL(url);
    const body = JSON.stringify(payload);
    const client = parsedUrl.protocol === 'https:' ? https : http;

    const request = client.request(
      parsedUrl,
      {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(body),
        },
