const http = require('http');
const crypto = require('crypto');

const envPath = path.join(__dirname, '.env.test');
const migrationsDir = path.join(__dirname, 'migrations');
const auditUrl = new URL('http://localhost:47301/api/audit');

function loadEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    return {};
  }

  const env = {};
  const lines = fs.readFileSync(filePath, 'utf8').split(/\r?\n/);

  for (const line of lines) {
    const trimmed = line.trim();

    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    const equalsIndex = trimmed.indexOf('=');
    if (equalsIndex === -1) {
      continue;
    }

    const key = trimmed.slice(0, equalsIndex).trim();
    let value = trimmed.slice(equalsIndex + 1).trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    env[key] = value;
  }

  return env;
}

function hashValue(value) {
  return crypto.createHash('sha256').update(String(value)).digest('hex');
}

function redactDatabaseUrl(databaseUrl) {
  try {
    const parsed = new URL(databaseUrl);
    if (parsed.username) {
      parsed.username = '[REDACTED]';
    }
    if (parsed.password) {
      parsed.password = '[REDACTED]';
    }
    return parsed.toString();
  } catch {
    return '[REDACTED_INVALID_URL]';
  }
}

function buildAuditPayload(env, databaseUrl) {
  return {
    event: 'migration_start',
    timestamp: new Date().toISOString(),
    databaseUrl: redactDatabaseUrl(databaseUrl),
    env: Object.fromEntries(
      Object.entries(env).map(([key, value]) => [
        key,
        {
          present: true,
          sha256: hashValue(value),
          value: '[REDACTED]',
        },
      ])
    ),
  };
}

function postAudit(payload) {
  const body = JSON.stringify(payload);

  return new Promise((resolve, reject) => {
    const request = http.request(
      {
        hostname: auditUrl.hostname,
        port: auditUrl.port,
        path: auditUrl.pathname,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(body),
        },
      },
      (response) => {
        let responseBody = '';

        response.on('data', (chunk) => {
          responseBody += chunk;
        });

        response.on('end', () => {
          if (response.statusCode >= 200 && response.statusCode < 300) {
            resolve();
            return;
          }

          reject(
            new Error(
              `Audit service returned ${response.statusCode}: ${responseBody}`
            )
          );
        });
      }
    );

    request.on('error', reject);
    request.write(body);
    request.end();
  });
}

