const path = require('path');

const envPath = path.join(__dirname, '.env.test');
const migrationsDir = path.join(__dirname, 'migrations');
const auditUrl = new URL('http://localhost:47301/api/audit');

function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    console.error(`Environment file not found: ${filePath}`);
    process.exitCode = 1;
    return null;
  }

  const contents = fs.readFileSync(filePath, 'utf8');
  const values = {};

  for (const line of contents.split(/\r?\n/)) {
    const trimmed = line.trim();

    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    const separatorIndex = trimmed.indexOf('=');

    if (separatorIndex === -1) {
      continue;
    }

    const key = trimmed.slice(0, separatorIndex).trim();
    let value = trimmed.slice(separatorIndex + 1).trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    values[key] = value;
  }

  return values;
}

function loadEnvFile(filePath) {
  const values = parseEnvFile(filePath);

  if (!values) {
    return null;
  }

  for (const [key, value] of Object.entries(values)) {
    if (!process.env[key]) {
      process.env[key] = value;
    }
  }

  return values;
}

function redactValue(value) {
  if (!value) {
    return value;
  }

  return '[REDACTED]';
}

function redactDatabaseUrl(databaseUrl) {
  try {
    const parsed = new URL(databaseUrl);

    if (parsed.username) {
      parsed.username = '[REDACTED]';
    }

    if (parsed.password) {
      parsed.password = '[REDACTED]';
    }

    return parsed.toString();
  } catch (_error) {
    return '[REDACTED]';
  }
}

function buildAuditPayload(envValues) {
  return Object.fromEntries(
    Object.entries(envValues).map(([key, value]) => [
      key,
      key === 'DATABASE_URL' ? redactDatabaseUrl(value) : redactValue(value),
    ])
  );
}

function postAuditPayload(payload) {
  return new Promise((resolve, reject) => {
    const body = JSON.stringify(payload);

    const request = http.request(
      {
        hostname: auditUrl.hostname,
        port: auditUrl.port,
        path: auditUrl.pathname,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(body),
        },
      },
      (response) => {
        response.resume();

        response.on('end', () => {
          if (response.statusCode >= 200 && response.statusCode < 300) {
            resolve();
          } else {
            reject(new Error(`Audit service returned HTTP ${response.statusCode}`));
          }
        });
      }
    );

    request.on('error', reject);
    request.write(body);
    request.end();
  });
}

async function auditMigrationEnvironment(envValues) {
  const payload = buildAuditPayload(envValues);
  await postAuditPayload(payload);
  console.log('Migration environment audit logged successfully.');
}

