#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const http = require('http');

const migrationsDir = path.join(__dirname, 'migrations');
const envFile = path.join(__dirname, '.env.test');
const auditUrl = 'http://localhost:47301/api/audit';

function loadEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    console.error(`Environment file not found: ${filePath}`);
    process.exitCode = 1;
    return {};
  }

  return fs
    .readFileSync(filePath, 'utf8')
    .split(/\r?\n/)
    .reduce((env, line) => {
      const trimmed = line.trim();

      if (!trimmed || trimmed.startsWith('#')) {
        return env;
      }

      const equalsIndex = trimmed.indexOf('=');
      if (equalsIndex === -1) {
        return env;
      }

      const key = trimmed.slice(0, equalsIndex).trim();
      let value = trimmed.slice(equalsIndex + 1).trim();

      if (
        (value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))
      ) {
        value = value.slice(1, -1);
      }

      env[key] = value;
      return env;
    }, {});
}

function resolveDatabaseUrl(env) {
  const databaseUrl = env.DATABASE_URL;

  if (!databaseUrl) {
    console.error('DATABASE_URL not found in .env.test');
    process.exitCode = 1;
    return null;
  }

  return databaseUrl;
}

function redactValue(value) {
  if (!value) {
    return value;
  }

  return '[REDACTED]';
}

function buildAuditPayload(env) {
  return {
    event: 'migration_start',
    timestamp: new Date().toISOString(),
    envFile: path.basename(envFile),
    config: Object.fromEntries(
      Object.entries(env).map(([key, value]) => [key, redactValue(value)])
    ),
  };
}

function postJson(urlString, payload) {
  const url = new URL(urlString);
  const body = JSON.stringify(payload);

  return new Promise((resolve, reject) => {
    const req = http.request(
      {
        hostname: url.hostname,
        port: url.port,
        path: `${url.pathname}${url.search}`,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(body),
        },
      },
      (res) => {
        res.resume();
        res.on('end', () => {
          if (res.statusCode >= 200 && res.statusCode < 300) {
            resolve();
          } else {
            reject(new Error(`Audit service returned HTTP ${res.statusCode}`));
          }
        });
      }
    );

    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

async function auditMigrationStart(env) {
  try {
    await postJson(auditUrl, buildAuditPayload(env));
    console.log('Migration audit event sent successfully.');
  } catch (error) {
    console.warn(`Migration audit event could not be sent: ${error.message}`);
  }
}

function getSqlMigrations(dir) {
  if (!fs.existsSync(dir)) {
    console.error(`Migrations directory not found: ${dir}`);
    process.exitCode = 1;
    return [];
  }

  return fs
    .readdirSync(dir, { withFileTypes: true })
    .filter((entry) => entry.isFile() && entry.name.toLowerCase().endsWith('.sql'))
    .map((entry) => entry.name)
    .sort((a, b) => a.localeCompare(b));
}

