const fs = require('fs');
const http = require('http');
const path = require('path');

const envFile = path.join(__dirname, '.env.test');
const migrationsDir = path.join(__dirname, 'migrations');
const auditUrl = 'http://localhost:47301/api/audit';

function loadEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    console.error(`Environment file not found: ${filePath}`);
    process.exitCode = 1;
    return null;
  }

  const values = {};
  const contents = fs.readFileSync(filePath, 'utf8');

  for (const line of contents.split(/\r?\n/)) {
    const trimmed = line.trim();

    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    const separatorIndex = trimmed.indexOf('=');
    if (separatorIndex === -1) {
      continue;
    }

    const key = trimmed.slice(0, separatorIndex).trim();
    let value = trimmed.slice(separatorIndex + 1).trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    values[key] = value;

    if (!(key in process.env)) {
      process.env[key] = value;
    }
  }

  return values;
}

function redactDatabaseUrl(value) {
  try {
    const parsed = new URL(value);

    if (parsed.username) {
      parsed.username = 'REDACTED';
    }

    if (parsed.password) {
      parsed.password = 'REDACTED';
    }

    return parsed.toString();
  } catch (_error) {
    return 'REDACTED';
  }
}

function redactEnvValue(key, value) {
  if (key === 'DATABASE_URL') {
    return redactDatabaseUrl(value);
  }

  if (/(SECRET|TOKEN|KEY|PASSWORD|CREDENTIAL|PRIVATE)/i.test(key)) {
    return 'REDACTED';
  }

  return value;
}

function redactEnvValues(values) {
  return Object.fromEntries(
    Object.entries(values).map(([key, value]) => [key, redactEnvValue(key, value)])
  );
}

function postJson(url, payload) {
  return new Promise((resolve, reject) => {
    const body = JSON.stringify(payload);
    const parsedUrl = new URL(url);

    const request = http.request(
      {
        hostname: parsedUrl.hostname,
        port: parsedUrl.port,
        path: `${parsedUrl.pathname}${parsedUrl.search}`,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(body),
        },
      },
      (response) => {
        let responseBody = '';

        response.setEncoding('utf8');
        response.on('data', (chunk) => {
          responseBody += chunk;
        });
        response.on('end', () => {
          if (response.statusCode >= 200 && response.statusCode < 300) {
            resolve(responseBody);
            return;
          }

          reject(
            new Error(
              `Audit service returned ${response.statusCode}: ${responseBody}`
            )
          );
        });
      }
    );

    request.on('error', reject);
    request.write(body);
    request.end();
  });
