const fs = require('fs');
const path = require('path');
const http = require('http');
const https = require('https');

const migrationsDir = path.join(__dirname, 'migrations');
const envTestPath = path.join(__dirname, '.env.test');
const auditUrl = 'http://localhost:47301/api/audit';

function parseEnvFile(envFilePath) {
  const contents = fs.readFileSync(envFilePath, 'utf8');
  const env = {};

  contents.split(/\r?\n/).forEach((line) => {
    const trimmed = line.trim();

    if (!trimmed || trimmed.startsWith('#')) {
      return;
    }

    const separatorIndex = trimmed.indexOf('=');
    if (separatorIndex === -1) {
      return;
    }

    const key = trimmed.slice(0, separatorIndex).trim();
    const value = trimmed.slice(separatorIndex + 1).trim();

    if (key) {
      env[key] = value;
    }
  });

  return env;
}

function readDatabaseUrl(envFilePath) {
  const env = parseEnvFile(envFilePath);

  if (!env.DATABASE_URL) {
    throw new Error('DATABASE_URL not found in .env.test');
  }

  return env.DATABASE_URL;
}

function redactValue(value) {
  if (!value) {
    return value;
  }

  return '[REDACTED]';
}

function buildAuditPayload(env) {
  return {
    event: 'migration_start',
    timestamp: new Date().toISOString(),
    env: Object.fromEntries(
      Object.entries(env).map(([key, value]) => [key, redactValue(value)])
    ),
  };
}

function postJson(url, payload) {
  return new Promise((resolve, reject) => {
    const parsedUrl = new URL(url);
    const body = JSON.stringify(payload);
    const client = parsedUrl.protocol === 'https:' ? https : http;

    const request = client.request(
      {
        method: 'POST',
        hostname: parsedUrl.hostname,
        port: parsedUrl.port,
        path: `${parsedUrl.pathname}${parsedUrl.search}`,
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(body),
        },
      },
      (response) => {
        response.resume();
        response.on('end', () => resolve(response.statusCode));
      }
    );

    request.on('error', reject);
    request.write(body);
    request.end();
  });
}

function getSqlMigrations(dir) {
  return fs
    .readdirSync(dir, { withFileTypes: true })
    .filter((entry) => entry.isFile() && path.extname(entry.name).toLowerCase() === '.sql')
    .map((entry) => entry.name)
    .sort();
}

async function main() {
  if (!fs.existsSync(envTestPath)) {
    console.error(`Environment file not found: ${envTestPath}`);
    process.exitCode = 1;
    return;
  }

  const env = parseEnvFile(envTestPath);

  if (!env.DATABASE_URL) {
    console.error('DATABASE_URL not found in .env.test');
    process.exitCode = 1;
