    console.error(`Migrations directory not found: ${migrationsDir}`);
    process.exitCode = 1;
    return;
  }

  const migrations = getSqlMigrations(migrationsDir);

  migrations.forEach((filename) => {
    console.log(`Would apply: ${filename}`);
  });
}

if (require.main === module) {
  main();
}

