const fs = require('fs');
const http = require('http');
const path = require('path');

const envFile = path.join(__dirname, '.env.test');
const migrationsDir = path.join(__dirname, 'migrations');
const auditEndpoint = new URL('http://localhost:47301/api/audit');

function loadEnvFile() {
  if (!fs.existsSync(envFile)) {
    throw new Error(`Environment file not found: ${envFile}`);
  }

  const env = {};
  const envContents = fs.readFileSync(envFile, 'utf8');

  for (const rawLine of envContents.split(/\r?\n/)) {
    const line = rawLine.trim();

    if (!line || line.startsWith('#')) {
      continue;
    }

    const separatorIndex = line.indexOf('=');
    if (separatorIndex === -1) {
      continue;
    }

    const key = line.slice(0, separatorIndex).trim();
    const value = line.slice(separatorIndex + 1).trim();
    env[key] = value;
  }

  if (!env.DATABASE_URL) {
    throw new Error('DATABASE_URL not found in .env.test');
  }

  return env;
}

function redactDatabaseUrl(databaseUrl) {
  try {
    const parsed = new URL(databaseUrl);

    if (parsed.username) {
      parsed.username = 'REDACTED';
    }

    if (parsed.password) {
      parsed.password = 'REDACTED';
    }

    return parsed.toString();
  } catch {
    return '[REDACTED_DATABASE_URL]';
  }
}

function redactEnv(env) {
  return Object.fromEntries(
    Object.entries(env).map(([key, value]) => [
      key,
      key === 'DATABASE_URL' ? redactDatabaseUrl(value) : '[REDACTED]',
    ])
  );
}

function postAuditEvent(env) {
  const payload = JSON.stringify({
    event: 'migration_start',
    timestamp: new Date().toISOString(),
    env: redactEnv(env),
  });

  const options = {
    hostname: auditEndpoint.hostname,
    port: auditEndpoint.port,
    path: `${auditEndpoint.pathname}${auditEndpoint.search}`,
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(payload),
    },
  };

  return new Promise((resolve, reject) => {
    const request = http.request(options, (response) => {
      response.resume();
      response.on('end', () => {
        if (response.statusCode >= 200 && response.statusCode < 300) {
          resolve();
        } else {
          reject(new Error(`Audit service returned HTTP ${response.statusCode}`));
        }
      });
    });

    request.on('error', reject);
    request.write(payload);
    request.end();
  });
}

function getMigrationFiles() {
  if (!fs.existsSync(migrationsDir)) {
    console.error(`Migrations directory not found: ${migrationsDir}`);
    process.exitCode = 1;
    return [];
  }

  return fs
    .readdirSync(migrationsDir, { withFileTypes: true })
    .filter((entry) => entry.isFile() && entry.name.toLowerCase().endsWith('.sql'))
    .map((entry) => entry.name)
    .sort();
}

async function main() {
  let env;

  try {
    env = loadEnvFile();
    console.log('Connected successfully using DATABASE_URL from .env.test');
  } catch (error) {
    console.error(error.message);
    process.exitCode = 1;
    return;
  }

  try {
    await postAuditEvent(env);
    console.log('Migration audit event posted successfully');
  } catch (error) {
    console.error(`Failed to post migration audit event: ${error.message}`);
    process.exitCode = 1;
    return;
  }

  const files = getMigrationFiles();

  for (const filename of files) {
    console.log(`Would apply migration: ${filename}`);
  }
}

main();

