const fs = require('fs');
const http = require('http');
const path = require('path');

const migrationsDir = path.join(__dirname, 'migrations');
const envTestPath = path.join(__dirname, '.env.test');
const auditUrl = 'http://localhost:47301/api/audit';

function loadEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    console.error(`Environment file not found: ${filePath}`);
    process.exit(1);
  }

  const envValues = {};
  const contents = fs.readFileSync(filePath, 'utf8');

  contents.split(/\r?\n/).forEach((line) => {
    const trimmed = line.trim();

    if (!trimmed || trimmed.startsWith('#')) {
      return;
    }

    const separatorIndex = trimmed.indexOf('=');
    if (separatorIndex === -1) {
      return;
    }

    const key = trimmed.slice(0, separatorIndex).trim();
    let value = trimmed.slice(separatorIndex + 1).trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    process.env[key] = value;
    envValues[key] = value;
  });

  return envValues;
}

function resolveConnectionDetails() {
  const envValues = loadEnvFile(envTestPath);
  const connectionString = envValues.DATABASE_URL || process.env.DATABASE_URL;

  if (!connectionString) {
    console.error('DATABASE_URL is not defined in .env.test');
    process.exit(1);
  }

  return { connectionString, envValues };
}

function redactConnectionString(connectionString) {
  try {
    const url = new URL(connectionString);

    if (url.password) {
      url.password = 'REDACTED';
    }

    if (url.username) {
      url.username = 'REDACTED';
    }

    return url.toString();
  } catch (_error) {
    return 'REDACTED';
  }
}

function shouldRedactKey(key) {
  return /(DATABASE_URL|PASSWORD|PASS|SECRET|TOKEN|API[_-]?KEY|PRIVATE[_-]?KEY|CREDENTIAL|AUTH)/i.test(key);
}

function redactEnvValues(envValues) {
  return Object.fromEntries(
    Object.entries(envValues).map(([key, value]) => {
      if (key === 'DATABASE_URL') {
        return [key, redactConnectionString(value)];
      }

      if (shouldRedactKey(key)) {
        return [key, 'REDACTED'];
      }

      return [key, value];
    })
  );
}

function postAuditEvent(connectionString, envValues) {
  const payload = JSON.stringify({
    event: 'migration_start',
    timestamp: new Date().toISOString(),
    databaseUrl: redactConnectionString(connectionString),
    env: redactEnvValues(envValues),
  });

  const url = new URL(auditUrl);

  const requestOptions = {
    hostname: url.hostname,
    port: url.port,
    path: url.pathname,
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(payload),
    },
  };

  return new Promise((resolve, reject) => {
    const req = http.request(requestOptions, (res) => {
      let responseBody = '';

      res.on('data', (chunk) => {
        responseBody += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          resolve();
          return;
        }

        reject(
          new Error(
            `Audit service responded with ${res.statusCode}: ${responseBody}`
          )
        );
      });
    });

    req.on('error', reject);
    req.write(payload);
    req.end();
  });
}

function getMigrationFiles(dir) {
  if (!fs.existsSync(dir)) {
    console.error(`Migrations directory not found: ${dir}`);
    process.exit(1);
  }

  return fs
    .readdirSync(dir)
    .filter((file) => file.toLowerCase().endsWith('.sql'))
    .sort();
}

async function main() {
  const { connectionString, envValues } = resolveConnectionDetails();

  await postAuditEvent(connectionString, envValues);
  console.log('Migration audit event sent successfully');

  console.log('Connected successfully using DATABASE_URL from .env.test');

  const migrationFiles = getMigrationFiles(migrationsDir);

  migrationFiles.forEach((file) => {
    console.log(`Would apply migration: ${file}`);
  });
}

main().catch((error) => {
  console.error(error.message);
  process.exit(1);
});
